BEGIN;
select set_config('request.jwt.claim.sub',(select user_id::text from public.memberships where organization_id='0e398095-cc22-421b-ae34-7bf0df8ad7b2' and active and role='admin' limit 1),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('request.jwt.claim.sub'),'role','authenticated')::text,true);
set local role authenticated;
DO $test$
DECLARE org uuid:='0e398095-cc22-421b-ae34-7bf0df8ad7b2';item uuid;vendor uuid;n1 public.procurement_needs;n2 public.procurement_needs;p uuid:=gen_random_uuid();a uuid;b uuid;g1 uuid:=gen_random_uuid();g2 uuid:=gen_random_uuid();data jsonb;rejected boolean;
BEGIN
 SELECT i.id INTO item FROM public.order_items i JOIN public.orders o ON o.id=i.order_id WHERE i.organization_id=org AND o.status NOT IN ('cancelled','completed') LIMIT 1;
 SELECT id INTO vendor FROM public.suppliers WHERE organization_id=org AND active LIMIT 1;
 IF item IS NULL OR vendor IS NULL THEN RAISE EXCEPTION 'Missing fixture';END IF;
 n1:=public.save_procurement_need_supplier(org,null,item,null,'Teste descartável produto A',13,'m',51,null,'Teste',false);
 n2:=public.save_procurement_need_supplier(org,null,item,null,'Teste descartável produto B',1,'un',100,null,'Teste',false);
 data:=jsonb_build_object('supplier_id',vendor,'ordered_at',current_date,'lines',jsonb_build_array(jsonb_build_object('id',n1.id,'unit_cost',51),jsonb_build_object('id',n2.id,'unit_cost',100)));
 PERFORM public.manage_purchasing(org,p,'order_later',data);
 PERFORM public.manage_purchasing(org,p,'order_later',data);
 IF (SELECT count(*) FROM public.purchase_items WHERE purchase_id=p)<>2 OR (SELECT count(*) FROM public.payables WHERE purchase_id=p)<>0 THEN RAISE EXCEPTION 'Encomenda duplicada ou financeiro antecipado';END IF;
 IF NOT (SELECT invoice_on_delivery AND status='awaiting_delivery' AND total=763 FROM public.purchases WHERE id=p) THEN RAISE EXCEPTION 'Previsão/status incorreto';END IF;
 SELECT id INTO a FROM public.purchase_items WHERE purchase_id=p AND procurement_need_id=n1.id;
 SELECT id INTO b FROM public.purchase_items WHERE purchase_id=p AND procurement_need_id=n2.id;
 data:=jsonb_build_object('invoice_id',g1,'ordered_at',current_date,'method','Boleto','installments',2,'paid',false,'lines',jsonb_build_array(jsonb_build_object('id',a,'actual_total',200)),'parts',jsonb_build_array(jsonb_build_object('amount',100,'due_date',current_date+30),jsonb_build_object('amount',100,'due_date',current_date+60)));
 rejected:=false;BEGIN PERFORM public.manage_purchasing(org,p,'invoice',data);EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Faturou item não recebido';END IF;
 PERFORM public.manage_purchasing(org,p,'receive',jsonb_build_object('delivery_at',current_date,'lines',jsonb_build_array(jsonb_build_object('id',a))));
 IF (SELECT status FROM public.purchases WHERE id=p)<>'awaiting_delivery' OR (SELECT status FROM public.purchase_items WHERE id=b)<>'ordered' THEN RAISE EXCEPTION 'Recebimento parcial concluiu os demais';END IF;
 rejected:=false;BEGIN PERFORM public.manage_purchasing(org,p,'invoice',data||jsonb_build_object('parts',jsonb_build_array(jsonb_build_object('amount',99,'due_date',current_date),jsonb_build_object('amount',100,'due_date',current_date))));EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 IF NOT rejected OR (SELECT invoice_id FROM public.purchase_items WHERE id=a) IS NOT NULL THEN RAISE EXCEPTION 'Fatura inválida deixou vínculo parcial';END IF;
 rejected:=false;BEGIN PERFORM public.manage_purchasing(org,p,'cancel','{"reason":"Teste cancelamento indevido"}');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Cancelou produto já recebido';END IF;
 PERFORM public.manage_purchasing(org,p,'invoice',data);
 PERFORM public.manage_purchasing(org,p,'invoice',data);
 IF (SELECT count(*) FROM public.payables WHERE purchase_id=p)<>2 OR (SELECT sum(amount) FROM public.payables WHERE purchase_id=p)<>200 THEN RAISE EXCEPTION 'Parcelas parciais incorretas/duplicadas';END IF;
 IF (SELECT sum(amount) FROM public.payable_allocations WHERE group_id=g1)<>200 THEN RAISE EXCEPTION 'Rateio parcial incorreto';END IF;
 rejected:=false;BEGIN PERFORM public.manage_purchasing(org,p,'invoice',data||jsonb_build_object('invoice_id',gen_random_uuid()));EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Mesmo item faturado duas vezes';END IF;
 PERFORM public.manage_purchasing(org,p,'receive',jsonb_build_object('delivery_at',current_date,'lines',jsonb_build_array(jsonb_build_object('id',b))));
 IF (SELECT status FROM public.purchases WHERE id=p)<>'completed' THEN RAISE EXCEPTION 'Recebimento total não concluiu';END IF;
 data:=jsonb_build_object('invoice_id',g2,'ordered_at',current_date,'method','PIX','installments',1,'paid',true,'received_at',current_date,'lines',jsonb_build_array(jsonb_build_object('id',b,'actual_total',398.01)),'parts',jsonb_build_array(jsonb_build_object('amount',398.01,'due_date',current_date)));
 PERFORM public.manage_purchasing(org,p,'invoice',data);
 IF (SELECT total FROM public.purchases WHERE id=p)<>598.01 OR (SELECT sum(amount) FROM public.payables WHERE purchase_id=p)<>598.01 OR (SELECT sum(paid_amount) FROM public.payables WHERE purchase_id=p)<>398.01 THEN RAISE EXCEPTION 'Totais reais e pagamento incorretos';END IF;
 IF (SELECT unit_cost FROM public.procurement_needs WHERE id=n1.id)<>51 THEN RAISE EXCEPTION 'Previsão original alterada';END IF;
 IF (SELECT sum(amount) FROM public.payable_allocations WHERE group_id=g2)<>398.01 THEN RAISE EXCEPTION 'Segundo rateio incorreto';END IF;
 rejected:=false;BEGIN PERFORM public.manage_purchasing(org,p,'confirm',data);EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Confirmação antiga duplicou faturamento';END IF;
END $test$;
RESET ROLE;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT 'PASS: one supplier order, no early finance, partial receipts/invoices, discount, exact cents, payment, forecast, replay protection' AS result;
ROLLBACK;
